CREATE TABLE users(id CHAR(36) PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(190),phone VARCHAR(60),organization_name VARCHAR(190),position VARCHAR(190),city VARCHAR(120),country VARCHAR(120) DEFAULT 'Cameroun',is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,role ENUM('admin','teacher','student') DEFAULT 'student',UNIQUE(user_id,role),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE courses(id CHAR(36) PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT,module_number INT,duration_minutes INT DEFAULT 90,max_participants INT DEFAULT 50,status ENUM('draft','published','live','completed','archived') DEFAULT 'draft',is_live TINYINT(1) DEFAULT 0,scheduled_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enrollments(id CHAR(36) PRIMARY KEY,student_id CHAR(36) NOT NULL,course_id CHAR(36) NOT NULL,status ENUM('active','completed','dropped') DEFAULT 'active',progress INT DEFAULT 0,enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,course_id),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE live_messages(id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,content TEXT NOT NULL,message_type VARCHAR(30) DEFAULT 'chat',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,title VARCHAR(255),message TEXT,type VARCHAR(40) DEFAULT 'info',is_read TINYINT(1) DEFAULT 0,course_id CHAR(36),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quizzes(id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,title VARCHAR(255),description TEXT,time_limit_minutes INT DEFAULT 30,passing_score INT DEFAULT 70,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quiz_questions(id CHAR(36) PRIMARY KEY,quiz_id CHAR(36) NOT NULL,question TEXT,options JSON,correct_answer INT DEFAULT 0,points INT DEFAULT 1,order_num INT DEFAULT 0,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts(id CHAR(36) PRIMARY KEY,quiz_id CHAR(36) NOT NULL,student_id CHAR(36) NOT NULL,score INT DEFAULT 0,total_points INT DEFAULT 0,percentage INT DEFAULT 0,passed TINYINT(1) DEFAULT 0,answers JSON,started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME);
CREATE TABLE proformas(id CHAR(36) PRIMARY KEY,proforma_number VARCHAR(100),client_name VARCHAR(255),client_email VARCHAR(190),client_phone VARCHAR(60),user_id CHAR(36),items JSON,total INT DEFAULT 0,currency VARCHAR(20) DEFAULT 'FCFA',status VARCHAR(40) DEFAULT 'draft',notes TEXT,valid_until DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_by CHAR(36));
CREATE TABLE company_info(id CHAR(36) PRIMARY KEY,name VARCHAR(255),address TEXT,phone VARCHAR(60),email VARCHAR(190),niu VARCHAR(100),rccm VARCHAR(100));
CREATE TABLE institutions(id CHAR(36) PRIMARY KEY,name VARCHAR(255),type VARCHAR(120) DEFAULT 'institution_financiere',address TEXT,city VARCHAR(120),country VARCHAR(120) DEFAULT 'Cameroun',phone VARCHAR(60),email VARCHAR(190),website TEXT,responsible_name VARCHAR(190),responsible_phone VARCHAR(60),responsible_email VARCHAR(190),responsible_position VARCHAR(190),niu VARCHAR(100),rccm VARCHAR(100),notes TEXT,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
